def chain_chain_follows(chain):
    chain = list(chain)
    chain.sort()
    for i in range(len(chain) - 1):
        if chain[i] == chain[i + 1][::-1]:
            break
    else:
        return chain

    # Find the first item that is not the first item of the chain
    for i in range(len(chain) - 1):
        if chain[i] != chain[i + 1][::-1]:
            break
    else:
        return chain

    # Find the last item that is not the last item of the chain
